"Blue":"Mavi",
"Green":"Yeşil",
"Violet":"Mor",
"Pink":"Pembe",
"Orange":"Turuncu",
"Teal":"Petrol",
"Gold":"Altın",
"Color":"Renk",
"Background":"Arka plan",
"Plain":"Sade",
"Tinted":"Renkli",
"Midnight":"Gece yarısı",
"Plum":"Erik",
"Ocean":"Okyanus",
"Forest":"Orman",
